import pandas as pd


def _plan_equal(a, b):
    a_na = pd.isna(a)
    b_na = pd.isna(b)
    if a_na and b_na:
        return True
    if a_na or b_na:
        return False
    return a == b


def run(inputs: dict) -> dict:
    dim = inputs["DIM_ACCOUNT"].copy()
    stg = inputs["STG_ACCOUNT"].copy()

    # Build initial state: account_id -> list of version dicts
    state = {}
    for _, row in dim.iterrows():
        acc = row["account_id"]
        ver = {
            "plan": row["plan"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
            "is_current": row["is_current"],
        }
        state.setdefault(acc, []).append(ver)

    # Sort staging by account_id, update_date ascending
    stg_sorted = stg.sort_values(
        by=["account_id", "update_date"], kind="mergesort"
    ).reset_index(drop=True)

    for _, srow in stg_sorted.iterrows():
        acc = srow["account_id"]
        s_plan = srow["plan"]
        s_date = srow["update_date"]

        versions = state.get(acc)

        if not versions:
            # No version at all -> insert open current version
            new_ver = {
                "plan": s_plan,
                "eff_start_date": s_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            state[acc] = [new_ver]
            continue

        # find version covering s_date
        v = None
        for cand in versions:
            start = cand["eff_start_date"]
            end = cand["eff_end_date"]
            if pd.isna(end):
                covers = start <= s_date
            else:
                covers = (start <= s_date) and (s_date < end)
            if covers:
                v = cand
                break

        if v is None:
            # earlier than earliest version
            f = min(versions, key=lambda x: x["eff_start_date"])
            new_ver = {
                "plan": s_plan,
                "eff_start_date": s_date,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            }
            versions.append(new_ver)
            continue

        if _plan_equal(v["plan"], s_plan):
            # no-op
            continue

        if s_date == v["eff_start_date"]:
            # same-day correction
            v["plan"] = s_plan
            continue

        # split v at s_date
        new_ver = {
            "plan": s_plan,
            "eff_start_date": s_date,
            "eff_end_date": v["eff_end_date"],
            "is_current": v["is_current"],
        }
        v["eff_end_date"] = s_date
        v["is_current"] = 0
        versions.append(new_ver)

    # Flatten state to output rows
    out_rows = []
    for acc, versions in state.items():
        for ver in versions:
            out_rows.append(
                {
                    "account_id": acc,
                    "plan": ver["plan"],
                    "eff_start_date": ver["eff_start_date"],
                    "eff_end_date": ver["eff_end_date"],
                    "is_current": ver["is_current"],
                }
            )

    out_df = pd.DataFrame(
        out_rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out_df.empty:
        out_df["account_id"] = out_df["account_id"].astype(dim["account_id"].dtype)
        out_df["is_current"] = out_df["is_current"].astype(dim["is_current"].dtype)

    return {"dim_account_out": out_df}
